// ── Shot Counter & CSV Writer ──────────────────────────────────────────────
// Placed after "Normalize & store IMM trx".
// Receives msg.payload = { machine_id, machine_name, parameters: { Total_Good_Count, ... } }
//
// Logic:
//  - shot_count : any CHANGE in Total_Good_Count → +1  (regardless of numeric value)
//  - counter    : increments only when new Total_Good_Count > 0  (status=1 logic)
//  - Shift A    : 08:00 – 20:00 local  →  ShiftA_YYYY-MM-DD.csv
//  - Shift B    : 20:00 – 08:00 local  →  ShiftB_YYYY-MM-DD.csv  (date = shift-start date)
//  - Both counters reset at every shift boundary, per machine independently.

const fs   = require('fs');
const path = require('path');

const CSV_DIR = '/data/eap_shots';

// ─── helpers ────────────────────────────────────────────────────────────────
function pad(n) { return String(n).padStart(2, '0'); }

function getShiftInfo(now) {
  const h   = now.getHours();  // local 0-23
  const fmt = (d) =>
    d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());

  if (h >= 8 && h < 20) {
    // Shift A — started today at 08:00
    return { shift: 'A', dateLabel: fmt(now) };
  }
  // Shift B — started at 20:00; if h < 8 the shift started yesterday
  const startDate = new Date(now);
  if (h < 8) startDate.setDate(startDate.getDate() - 1);
  return { shift: 'B', dateLabel: fmt(startDate) };
}

function csvFilePath(shift, dateLabel) {
  return path.join(CSV_DIR, 'Shift' + shift + '_' + dateLabel + '.csv');
}

function ensureDir(dir) {
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
}

function appendRow(filePath, row) {
  const needHeader = !fs.existsSync(filePath);
  if (needHeader) {
    fs.writeFileSync(
      filePath,
      'timestamp,shift,date_label,machine_id,machine_name,total_good_count,machine_shot_count,counter\n',
      'utf8'
    );
  }
  fs.appendFileSync(
    filePath,
    [
      row.timestamp, row.shift, row.date_label,
      row.machine_id, row.machine_name,
      row.total_good_count, row.machine_shot_count, row.counter
    ].join(',') + '\n',
    'utf8'
  );
}

// ─── guard ──────────────────────────────────────────────────────────────────
const entry = msg.payload;
if (!entry || !entry.parameters) return null;

const rawGC = entry.parameters.Total_Good_Count;
if (rawGC === undefined || rawGC === null || rawGC === '') return null;

const machineId   = entry.machine_id   !== undefined ? entry.machine_id : null;
const machineName = String(entry.machine_name || 'UNKNOWN').trim();
const storeKey    = machineId !== null ? ('m' + machineId) : machineName.toUpperCase();

const now       = new Date();
const shiftInfo = getShiftInfo(now);
const shiftKey  = shiftInfo.shift + '_' + shiftInfo.dateLabel;  // e.g. "A_2026-10-07"

// ─── per-machine persistent state ───────────────────────────────────────────
const allState = global.get('EAP_SHOT_STATE') || {};
let   st       = allState[storeKey] || { prevGC: null, shotCount: 0, counter: 0, shiftKey: '' };

// Shift boundary → reset counters (prevGC kept to avoid false-fire on first message)
if (st.shiftKey !== shiftKey) {
  st.shotCount = 0;
  st.counter   = 0;
  st.shiftKey  = shiftKey;
}

const newGC  = String(rawGC).trim();
const prevGC = st.prevGC;      // null on very first message for this machine

let shotFired = 0;

if (prevGC !== null && prevGC !== newGC) {
  // Any change in Total_Good_Count value = 1 shot
  shotFired    = 1;
  st.shotCount += 1;

  // Counter: only when new value is numeric AND > 0  ("status turns 1" logic)
  const numGC = parseFloat(newGC);
  if (Number.isFinite(numGC) && numGC > 0) {
    st.counter += 1;
  }
}

st.prevGC          = newGC;
allState[storeKey] = st;
global.set('EAP_SHOT_STATE', allState);

// ─── CSV append ─────────────────────────────────────────────────────────────
try {
  ensureDir(CSV_DIR);
  const ts = now.getFullYear() + '-' +
             pad(now.getMonth() + 1) + '-' +
             pad(now.getDate())      + 'T' +
             pad(now.getHours())     + ':' +
             pad(now.getMinutes())   + ':' +
             pad(now.getSeconds());

  appendRow(csvFilePath(shiftInfo.shift, shiftInfo.dateLabel), {
    timestamp          : ts,
    shift              : shiftInfo.shift,
    date_label         : shiftInfo.dateLabel,
    machine_id         : machineId !== null ? machineId : '',
    machine_name       : machineName,
    total_good_count   : newGC,
    machine_shot_count : st.shotCount,
    counter            : st.counter
  });
} catch (e) {
  node.warn('CSV write error: ' + e.message);
}

// ─── output ──────────────────────────────────────────────────────────────────
msg.payload = {
  machine_id         : machineId,
  machine_name       : machineName,
  Total_Good_Count   : newGC,
  machine_shot_count : st.shotCount,
  counter            : st.counter,
  shift              : shiftInfo.shift,
  shift_date         : shiftInfo.dateLabel,
  shot_fired         : shotFired
};

node.status({
  fill : shotFired ? 'green' : 'blue',
  shape: 'dot',
  text : machineName + ' GC=' + newGC + ' shots=' + st.shotCount + ' ctr=' + st.counter
});

return msg;

global.set('EAP_SHOT_STATE', {});
node.status({ fill:'yellow', shape:'ring', text:'all shot counters reset ' + new Date().toLocaleTimeString() });
node.warn('EAP_SHOT_STATE cleared manually');
return null;
